import json
import os

from .errors import ProofFormatError, RootUnavailable
from .hashes import (
    CHUNK_SIZE,
    DIGEST,
    file_digest_from_chunk_hashes,
    hash_file_chunks,
    merkle_root,
)

VERSION = 1
PROOF_FORMAT = "state-proof"


def _iter_regular_files(root):
    """生成 (POSIX 相对路径, 绝对路径)，仅普通文件；顺序由调用方排序。"""
