        raise ProofFormatError("proof_id 必须与 root 摘要一致")

    if not isinstance(data.get("file_count"), int) or data["file_count"] != len(
        norm_files
    ):
        raise ProofFormatError("file_count 与文件清单不一致")

    return {
        "version": VERSION,
        "format": PROOF_FORMAT,
        "hash_algorithm": DIGEST,
        "chunk_size": CHUNK_SIZE,
        "proof_id": proof_id,
        "root": root,
