def _read_existing(path, proof_id):
    try:
        with open(path, "r", encoding="utf-8") as fh:
            data = json.load(fh)
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise StateConflict(f"状态文件不可解析: {path}: {exc}") from exc

    if not isinstance(data, dict) or data.get("format") != STATE_FORMAT:
        raise StateConflict(f"状态文件格式非法: {path}")
    if data.get("version") != VERSION:
        raise StateConflict(f"状态文件版本不受支持: {data.get('version')!r}")
    if data.get("proof_id") != proof_id:
        raise StateConflict(
            "状态文件属于不同 proof_id",
            details={
                "state_proof_id": data.get("proof_id"),
                "proof_id": proof_id,
            },
        )
    if not isinstance(data.get("history"), list) or not isinstance(
        data.get("total_challenges"), int
    ):
        raise StateConflict(f"状态文件结构非法: {path}")

    # 以 history 为准回填聚合，防止手改汇总字段。
    merged = _empty_container(proof_id)
    for i, rec in enumerate(data["history"]):
        if not isinstance(rec, dict) or not isinstance(
            rec.get("challenge_id"), str
        ):
            raise StateConflict(f"状态历史第 {i} 条非法: {path}")
        merged["history"].append(rec)
        merged["total_challenges"] += 1
        merged["requested_samples"] += int(rec.get("requested_samples", 0))
        merged["checked_samples"] += int(rec.get("checked_samples", 0))
        merged["missing_samples"] += int(rec.get("missing_samples", 0))
        merged["mismatched_samples"] += int(rec.get("mismatched_samples", 0))
    last = merged["history"][-1] if merged["history"] else None
    if last is not None:
        merged["last_challenge_id"] = last["challenge_id"]
        merged["last_seed"] = last.get("seed")
        merged["last_valid"] = last.get("valid")
        merged["last_failure_reason"] = last.get("failure_reason")
        merged["last_challenge_at"] = last.get("challenged_at")
    return merged


